const fs = require('fs');
const path = require('path');

const inp = $input.first().json;
const { topic, audience, runtime, kieApiKey } = inp;

const slug = topic.toLowerCase()
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '')
  .substring(0, 50);

const ts = new Date().toISOString()
  .replace(/[^0-9]/g, '')
  .substring(0, 12);

const episodeDir = '/Users/jneal/n8n_projects/' + slug + '_' + ts;
const dirs = ['scripts', 'audio', 'images', 'videos', 'clips', 'music', 'sfx'];

fs.mkdirSync(episodeDir, { recursive: true });
for (const d of dirs) {
  fs.mkdirSync(path.join(episodeDir, d), { recursive: true });
}

console.log('Episode directory created: ' + episodeDir);

return [{ json: { topic, audience, runtime, kieApiKey, episodeDir, slug } }];

const fs = require('fs');
const inp = $input.first().json;

const systemPrompt = fs.readFileSync(
  '/Users/jneal/n8n_projects/ruins_untold_system_prompts/research_agent.md',
  'utf-8'
);

const userInput = JSON.stringify({
  topic: inp.topic,
  audience: inp.audience,
  runtime: inp.runtime
}, null, 2);

const fullPrompt = systemPrompt + '\n\n---\n\nYour input:\n\n' + userInput;

console.log('Calling Research Agent (prompt length: ' + fullPrompt.length + ')');

const res = await fetch('http://host.docker.internal:3333/generate', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ prompt: fullPrompt })
});

const data = await res.json();
if (data.exitCode !== 0) throw new Error('Research Agent failed: ' + data.error);

let raw = data.output.trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();

let pkg;
try {
  pkg = JSON.parse(raw);
} catch (e) {
  const s = raw.indexOf('{');
  const en = raw.lastIndexOf('}');
  if (s === -1 || en === -1) throw new Error('Could not parse research package JSON');
  pkg = JSON.parse(raw.substring(s, en + 1));
}

const outPath = inp.episodeDir + '/scripts/research_package.json';
fs.writeFileSync(outPath, JSON.stringify(pkg, null, 2), 'utf-8');
console.log('Research package saved: ' + outPath);

return [{ json: { ...inp, researchPackage: pkg, researchPackagePath: outPath } }];

