const fs = require('fs');
const inp = $input.first().json;

// ── KIE.AI CONFIGURATION ──────────────────────────────────────────────────────
// Update the endpoint and key format to match your Kie.ai account
const KIE_API_KEY = inp.kieApiKey;
const KIE_TTS_URL = 'https://api.kie.ai/v1/tts/generate'; // confirm with Kie.ai docs
// ─────────────────────────────────────────────────────────────────────────────

const { voicePackage, episodeDir } = inp;
const segments = voicePackage.segments;

console.log('Starting TTS for ' + segments.length + ' segments...');

let prevRequestId = null;
const updatedSegments = [];

for (let i = 0; i < segments.length; i++) {
  const seg = segments[i];
  console.log('Generating segment ' + (i + 1) + '/' + segments.length + ': ' + seg.segment_id);

  const payload = {
    model_id: voicePackage.model,
    voice_id: voicePackage.voice_id,
    text: seg.voice_optimized_text,
    voice_settings: {
      stability: 0.5,
      similarity_boost: 0.75,
      style: 0,
      use_speaker_boost: true
    },
    previous_request_ids: prevRequestId ? [prevRequestId] : []
  };

  const res = await fetch(KIE_TTS_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + KIE_API_KEY
    },
    body: JSON.stringify(payload)
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error('TTS failed for ' + seg.segment_id + ': ' + res.status + ' ' + errText.substring(0, 200));
  }

  const audioBuffer = Buffer.from(await res.arrayBuffer());
  const seqPad = String(seg.sequence).padStart(3, '0');
  const audioFile = episodeDir + '/audio/seg_' + seqPad + '_' + seg.segment_id + '.mp3';
  fs.writeFileSync(audioFile, audioBuffer);

  prevRequestId = res.headers.get('request-id')
    || res.headers.get('x-request-id')
    || res.headers.get('x-elevenlabs-request-id')
    || null;

  updatedSegments.push({ ...seg, audio_file: audioFile, request_id: prevRequestId });
  console.log('  Saved: ' + audioFile + ' (' + audioBuffer.length + ' bytes)');
}

voicePackage.segments = updatedSegments;
fs.writeFileSync(inp.voicePackagePath, JSON.stringify(voicePackage, null, 2), 'utf-8');
console.log('TTS complete. voice_package.json updated with audio file paths.');

return [{ json: { ...inp, voicePackage, ttsComplete: true, segmentCount: updatedSegments.length } }];

const { execSync } = require('child_process');
const fs = require('fs');
const inp = $input.first().json;

const { voicePackage, episodeDir } = inp;

const segs = voicePackage.segments
  .filter(function(s) { return s.audio_file && fs.existsSync(s.audio_file); })
  .sort(function(a, b) { return a.sequence - b.sequence; });

if (segs.length === 0) throw new Error('No audio segment files found to concatenate');

console.log('Concatenating ' + segs.length + ' segments...');

const concatPath = episodeDir + '/audio/concat.txt';
const lines = segs.map(function(s) { return "file '" + s.audio_file + "'"; });
fs.writeFileSync(concatPath, lines.join('\n'), 'utf-8');

const outputPath = episodeDir + '/audio/voiceover_final.mp3';

execSync(
  'ffmpeg -y -f concat -safe 0 -i "' + concatPath + '" -c copy "' + outputPath + '"',
  { timeout: 120000 }
);

console.log('Voiceover final saved: ' + outputPath);

return [{ json: { ...inp, voiceFinalPath: outputPath, phase1Complete: true } }];
